```java
// All RuntimeExceptions — no try-catch required by compiler
String s = null;
s.length(); // NullPointerException

int[] arr = new int[3];
arr[5] = 10; // ArrayIndexOutOfBoundsException

Object obj = "hello";
Integer num = (Integer) obj; // ClassCastException
```

```java
try {
    // read from database
} catch (SQLException e) {
    // wrap with cause preserved
    throw new ServiceException("Failed to load user", e);
}
// serviceException.getCause() returns the original SQLException
```

```java
// Before Java 7 — duplicate handling
try { riskyMethod(); }
catch (IOException e) { log.error("Error", e); }
catch (SQLException e) { log.error("Error", e); }

// Java 7+ multi-catch
try { riskyMethod(); }
catch (IOException | SQLException e) { log.error("Error", e); }
```

```java
public static void main(String[] args) {
    try {
        System.out.println("try");
        throw new RuntimeException("boom");
    } finally {
        System.out.println("finally");
    }
}
// Output: try → finally → exception propagates
```
